<?php namespace Workspace;
$hidden=static function(string $act)use($week,$snapshot){formFields($act);echo '<input type="hidden" name="week" value="',h($week),'"><input type="hidden" name="snapshot" value="',h($snapshot),'">';};
$totals=[];$sourcePeople=$people;foreach($allocations as $r){$totals[$r['user_id']]=($totals[$r['user_id']]??0)+(int)$r['minutes'];$sourcePeople[$r['user_id']]??='Бывший участник #'.$r['user_id'];}
?>
<section class="panel"><h2>Планирование нескольких команд</h2><p>Общий календарь сотрудника на неделю в текущей организации. Распределение использует проектную доступность; согласованные табели и ставки не меняются.</p><form method="get" class="formgrid"><input type="hidden" name="p" value="capacity"><label>Понедельник недели<input type="date" name="week" value="<?= h($week) ?>" required></label><button>Показать</button></form><p><a href="<?= h(url('team')) ?>">Управление составом команд</a> · <a href="<?= h(url('capacity',['week'=>(new \DateTimeImmutable($week))->modify('-1 week')->format('Y-m-d')])) ?>">Предыдущая неделя</a> · <a href="<?= h(url('capacity',['week'=>capacityCurrentWeek()])) ?>">Текущая</a> · <a href="<?= h(url('capacity',['week'=>(new \DateTimeImmutable($week))->modify('+1 week')->format('Y-m-d')])) ?>">Следующая неделя</a></p><?php if(!$editable): ?><p>Прошедшая неделя: только чтение в этом разделе.</p><?php endif ?></section>
<section class="panel"><h2>Календарь доступности (минуты в день)</h2><p>Ноль означает отсутствие доступности. Пустой календарь — неизвестная ёмкость, не нулевая. Сначала перенесите назначения, если планируется отпуск или сокращение часов.</p>
<?php foreach($people as $uid=>$name):$c=$calendars[$uid]??null;$allocated=$totals[$uid]??0; ?><details><summary><?= h($name.' · '.($c?capacityTotal($c).' мин. доступно':'нет календаря').' · '.$allocated.' мин. назначено'.($c?' · остаток '.(capacityTotal($c)-$allocated).' мин.':'')) ?></summary><?php if($c): ?><p><?= h($c['reason']) ?></p><table><thead><tr><?php foreach(CAPACITY_DAYS as $label): ?><th><?= h($label) ?></th><?php endforeach ?></tr></thead><tbody><tr><?php foreach(CAPACITY_DAYS as $day=>$label): ?><td><?= h($c[$day]) ?></td><?php endforeach ?></tr></tbody></table><?php endif ?><?php if($editable): ?><form method="post" class="formgrid"><?php $hidden('capacity.calendar') ?><input type="hidden" name="user_id" value="<?= h($uid) ?>"><?php foreach(CAPACITY_DAYS as $day=>$label): ?><label><?= h($label) ?><input type="number" name="<?= h($day) ?>" min="0" max="1440" value="<?= h($c[$day]??0) ?>" required></label><?php endforeach ?><label>Причина / отсутствие<input name="reason" maxlength="500" value="<?= h($c['reason']??'') ?>"></label><button>Сохранить календарь</button></form><?php endif ?></details><?php endforeach ?></section>
<section class="panel"><h2>Распределение по проектам и командам</h2><p>Для одной пары сотрудник–проект на неделю назначается одна команда. Старые назначения без команды отображаются отдельно. Недоступные или превышающие календарь назначения исключены из прогноза.</p><table><thead><tr><th>Команда</th><th>Проект</th><th>Сотрудник</th><th>Минуты</th><th>Проверка</th></tr></thead><tbody><?php foreach($allocations as $r):if((int)$r['minutes']===0)continue; ?><tr><td><?= h($teams[$r['team_id']]??'Без команды') ?></td><td><a href="<?= h(url('workload',['project'=>$r['project_id'],'week'=>$week])) ?>"><?= h($projects[$r['project_id']]) ?></a></td><td><?= h($sourcePeople[$r['user_id']]) ?></td><td><?= h($r['minutes']) ?></td><td><?= h($r['valid']?'Подтверждена календарём':'Требуется сверка') ?></td></tr><?php endforeach ?></tbody></table><h3>Подтверждённая ёмкость команд</h3><?php foreach($teamTotals as $id=>$minutes): ?><p><?= h(($teams[$id]??'Без команды').' — '.$minutes.' мин.') ?></p><?php endforeach ?>
<?php if($editable&&$projects&&$sourcePeople): ?><h3>Назначить или изменить ёмкость</h3><form method="post" class="formgrid"><?php $hidden('capacity.assign') ?><label>Сотрудник<select name="user_id"><?php selectOptions($sourcePeople) ?></select></label><label>Проект<select name="project_id"><?php selectOptions($projects) ?></select></label><label>Команда<select name="team_id"><?php selectOptions([''=>'Только для снятия назначения']+$teams) ?></select></label><label>Всего минут (0 — снять)<input type="number" name="minutes" min="0" max="10080" required></label><label>Причина<input name="reason" maxlength="500" required></label><button>Сохранить назначение</button></form><?php endif ?>
<?php if($editable&&$projects&&$people&&$teams&&$allocations): ?><h3>Перераспределение и замещение</h3><p>Для переноса между проектами выберите того же сотрудника, для замещения — другого. Из исходного назначения вычитается ровно столько минут, сколько добавляется целевому. Исполнители задач не меняются автоматически.</p><form method="post" class="formgrid"><?php $hidden('capacity.transfer') ?><label>Исходный сотрудник<select name="user_id"><?php selectOptions($sourcePeople) ?></select></label><label>Исходный проект<select name="project_id"><?php selectOptions($projects) ?></select></label><label>Целевой сотрудник<select name="target_user"><?php selectOptions($people) ?></select></label><label>Целевой проект<select name="target_project"><?php selectOptions($projects) ?></select></label><label>Целевая команда<select name="target_team"><?php selectOptions($teams) ?></select></label><label>Перенос минут<input type="number" name="minutes" min="1" max="10080" required></label><label>Причина переноса / замещения<input name="reason" maxlength="500" required></label><button>Перенести ёмкость</button></form><?php endif ?></section>
<section class="panel"><h2>Прогноз очереди на 8 недель</h2><p>Остаток оценённой трудоёмкости открытых задач: оценка незакрытого спринта минус утверждённые минуты, не меньше нуля. Задачи без положительной оценки и заблокированные отмечены отдельно. Используются только явно подтверждённые полные будущие недели; текущая и прошлые недели не уменьшают прогноз. Это агрегатный сценарий, не обещание срока: зависимости, навыки и новые задачи могут изменить результат.</p><?php foreach($projects as $id=>$title):$d=$demand[$id]; ?><details><summary><?= h($title.' · '.$d['minutes'].' мин. остатка · '.$d['unknown'].' без оценки · '.$d['blocked'].' блокировано из '.$d['tasks']) ?></summary><table><thead><tr><th>Неделя</th><th>Ёмкость</th><th>Покрытие</th><th>Остаток</th></tr></thead><tbody><?php foreach($forecast[$id]??[] as $w=>$r): ?><tr><td><?= h($w) ?></td><td><?= h($r['capacity']) ?></td><td><?= h($r['covered']) ?></td><td><?= h($r['remaining']) ?></td></tr><?php endforeach ?></tbody></table></details><?php endforeach ?></section>
<section class="panel"><h2>Последние изменения плана</h2><?php foreach($history as $r): ?><p><?= h($r['created_at'].' · '.$r['name'].' · '.$r['event'].' · сотрудник #'.$r['object_id'].' · '.$r['detail']) ?></p><?php endforeach ?><?php if(!$history): ?><p>Нет записей.</p><?php endif ?></section>
